import{_ as t}from"./chunks/100.Bym1HttY.js";import{_ as a,o,c as r,ak as n}from"./chunks/framework.Ba6sv-31.js";const s="/projects/AiBlockSensor/en/latest/assets/1.CRELBEQZ.webp",i="/projects/AiBlockSensor/en/latest/assets/2.tU_UE3AW.webp",c="/projects/AiBlockSensor/en/latest/assets/3.l0cjGppv.webp",l="/projects/AiBlockSensor/en/latest/assets/4.D5xSDV7P.webp",y=JSON.parse('{"title":"7. Infrared Obstacle Avoidance Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/7. Infrared Obstacle Avoidance Sensor.md","filePath":"docs/7. Infrared Obstacle Avoidance Sensor.md"}'),d={name:"docs/7. Infrared Obstacle Avoidance Sensor.md"};function h(p,e,m,u,g,b){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="_7-infrared-obstacle-avoidance-sensor" tabindex="-1">7. Infrared Obstacle Avoidance Sensor <a class="header-anchor" href="#_7-infrared-obstacle-avoidance-sensor" aria-label="Permalink to &quot;7. Infrared Obstacle Avoidance Sensor&quot;">​</a></h1><h2 id="_7-1-introduction" tabindex="-1">7.1 Introduction <a class="header-anchor" href="#_7-1-introduction" aria-label="Permalink to &quot;7.1 Introduction&quot;">​</a></h2><p>This section introduces the infrared obstacle avoidance sensor, designed to detect obstacles in its forward path. The sensor features an infrared transmitter and an infrared receiver. When an obstacle enters the detection range, the emitted infrared light reflects back to the receiver. This sensor is widely used for obstacle avoidance in robots and smart cars.</p><img loading="lazy" height="261" width="531" src="'+s+'" class="common_img" style="width:300px;"><h2 id="_7-2-technical-specifications" tabindex="-1">7.2 Technical Specifications <a class="header-anchor" href="#_7-2-technical-specifications" aria-label="Permalink to &quot;7.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Adjustment method</td><td style="text-align:center;">Miniature potentiometer adjustment</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">23.0 × 54.0 × 18.8 mm</td></tr></tbody></table><h2 id="_7-3-adjustment-method" tabindex="-1">7.3 Adjustment Method <a class="header-anchor" href="#_7-3-adjustment-method" aria-label="Permalink to &quot;7.3 Adjustment Method&quot;">​</a></h2><p>Turn the onboard miniature potentiometer to adjust the detection range. Turn clockwise to increase the detection distance. Turn counterclockwise to decrease the detection distance.</p><h2 id="_7-4-hands-on-project" tabindex="-1">7.4 Hands-On Project <a class="header-anchor" href="#_7-4-hands-on-project" aria-label="Permalink to &quot;7.4 Hands-On Project&quot;">​</a></h2><h3 id="_7-4-1-project-introduction" tabindex="-1">7.4.1 Project Introduction <a class="header-anchor" href="#_7-4-1-project-introduction" aria-label="Permalink to &quot;7.4.1 Project Introduction&quot;">​</a></h3><p>This project uses the infrared obstacle avoidance sensor to detect forward obstacles and pairs it with the buzzer for audio feedback. When the sensor detects an obstacle, the buzzer plays an alert tone. When the path is clear, the buzzer turns off, clearly showing how the obstacle avoidance sensor works.</p><h3 id="_7-4-2-hardware-wiring" tabindex="-1">7.4.2 Hardware Wiring <a class="header-anchor" href="#_7-4-2-hardware-wiring" aria-label="Permalink to &quot;7.4.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the infrared obstacle avoidance sensor to port <strong>A</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="371" width="953" src="'+i+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among A, B, C, or D on the controller. Ensure that the port selected in the program matches the physical wiring.</strong></p></div><h3 id="_7-4-3-adding-extensions" tabindex="-1">7.4.3 Adding Extensions <a class="header-anchor" href="#_7-4-3-adding-extensions" aria-label="Permalink to &quot;7.4.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Avoid obstacle sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+c+'" class="common_img" style="width:800px;"><h3 id="_7-4-4-complete-program-and-analysis" tabindex="-1">7.4.4 Complete Program and Analysis <a class="header-anchor" href="#_7-4-4-complete-program-and-analysis" aria-label="Permalink to &quot;7.4.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Inside the main program loop, continuously check the status of the infrared obstacle avoidance sensor.</p></li><li><p>Condition check: Read the sensor on port A to detect whether an obstacle is present.</p><ul><li><p>If an obstacle is detected: Play note C5 for half a beat.</p></li><li><p>If no obstacle is detected: Turn off the buzzer to stop sound output.</p></li></ul></li></ol><img loading="lazy" height="373" width="763" src="'+l+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1fLfLXEVjSMZdojOq7C44xJqZIBm4MDem?usp=sharing" target="_blank" rel="noreferrer">Program Files/ 07 Infrared Obstacle Avoidance Sensor.sb3</a>.</strong></p></div><h3 id="_7-4-5-program-upload" tabindex="-1">7.4.5 Program Upload <a class="header-anchor" href="#_7-4-5-program-upload" aria-label="Permalink to &quot;7.4.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+t+'" class="common_img" style="width:800px;"><h3 id="_7-4-6-program-outcome" tabindex="-1">7.4.6 Program Outcome <a class="header-anchor" href="#_7-4-6-program-outcome" aria-label="Permalink to &quot;7.4.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, bring an object close to the sensor. The buzzer sounds an alert tone as soon as an obstacle is detected. Move the object away, and the buzzer stops immediately.</p>',27)])])}const x=a(d,[["render",h]]);export{y as __pageData,x as default};
